css:
/* Кадр продукта вырастает по прокрутке. Двигается только transform: рамка растёт .84 → 1,
   картинка внутри встречно уменьшается 1.12 → 1 (её «открывают», а не просто увеличивают).
   Без поддержки и без JS кадр сразу стоит в конечном виде. */
.mzs {
  --mzs-from: .84;        /* начальный масштаб рамки; меньше .8 — уже «слайд-шоу» */
  --mzs-img-from: 1.12;   /* встречный масштаб картинки; 1 — без него (мелкий текст интерфейса не мылится) */
  --mzs-radius: 24px;
  padding-block: 64px;
}
.mzs__title { margin: 0 0 12px; font-size: clamp(28px, 3.4vw, 44px); line-height: 1.15; }
.mzs__lead { margin: 0 0 32px; max-width: 48ch; color: var(--text-muted, #555b66); }
/* Шкала прокрутки висит на неподвижной обёртке: у рамки свой transform, и мерить её саму нельзя */
.mzs__stage { view-timeline: --mzs block; }
.mzs__frame {
  margin: 0;
  aspect-ratio: 16 / 9;                /* место под кадр занято до загрузки: сдвига макета нет */
  overflow: hidden;
  overflow: clip;
  border-radius: var(--mzs-radius);
  background: var(--surface, #f2f3f5);
  transform-origin: 50% 50%;
}
.mzs__img { display: block; width: 100%; height: 100%; object-fit: cover; }
@media (max-width: 767px) {             /* телефон: одно свойство и меньше ход */
  .mzs { --mzs-from: .94; --mzs-img-from: 1; --mzs-radius: 16px; }
}
@keyframes mzs-frame { from { transform: scale(var(--mzs-from)); } to { transform: none; } }
@keyframes mzs-img { from { transform: scale(var(--mzs-img-from)); } to { transform: none; } }
@media (prefers-reduced-motion: no-preference) {
  /* Chrome, Edge, Safari 26: ведёт сама прокрутка, без JS и в отдельном потоке */
  @supports (animation-timeline: view()) {
    .mzs__frame, .mzs__img {
      animation: mzs-frame 1ms linear both; /* 1ms нужен Firefox: без длительности он не применяет анимацию */
      animation-timeline: --mzs;            /* строго ПОСЛЕ animation: сокращённая запись сбрасывает шкалу */
      animation-range: entry 0% cover 40%;  /* начинает, когда верх кадра у низа экрана; полный размер — когда кадр почти весь в экране */
    }
    .mzs__img { animation-name: mzs-img; }
    /* JS ставит .mzs-js, если шкала замерла (кадр внутри непрокручиваемого контейнера) — тогда кадр ведёт он */
    .mzs__stage.mzs-js .mzs__frame, .mzs__stage.mzs-js .mzs__img { animation: none; }
  }
}
/* Уровень 1 (убрать): рост по прокрутке — движение крупной площади, при reduce кадр сразу в конечном виде.
   !important перекрывает и inline-стиль запасного JS */
@media (prefers-reduced-motion: reduce) {
  .mzs__frame, .mzs__img { animation: none !important; transform: none !important; }
}

js:
// Запасной путь: ведёт кадр там, где CSS-шкала прокрутки не работает (Firefox) или замерла.
(() => {
  const all = [...document.querySelectorAll('[data-mzs]')];
  if (!all.length) return;
  const cssOk = !!(window.CSS && CSS.supports('animation-timeline', 'view()'));
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  const js = []; let raf = 0;
  // Шкала «замерла»: кадр внутри непрокручиваемого контейнера (частый случай — html, body { overflow-x: hidden })
  const frozen = (s) => {
    const src = s.querySelector('.mzs__frame')?.getAnimations()[0]?.timeline?.source;
    return !!src && src !== document.scrollingElement && src.scrollHeight <= src.clientHeight;
  };
  const pick = () => all.forEach((s) => {
    if (s.classList.contains('mzs-js') || (cssOk && !frozen(s))) return;
    s.classList.add('mzs-js'); js.push(s); // .mzs-js снимает CSS-анимацию — кадром управляет JS
  });
  const v = (el, name, d) => parseFloat(getComputedStyle(el).getPropertyValue(name)) || d;
  const frame = () => {
    raf = 0;
    if (reduce.matches) return;
    const vh = innerHeight;
    const plan = js.map((s) => { // сначала все чтения
      const r = s.getBoundingClientRect();
      if (r.bottom < -200 || r.top > vh + 200) return null;
      const p = Math.min(1, Math.max(0, (vh - r.top) / (0.4 * (vh + r.height)))); // = entry 0% … cover 40%
      return [s, p, v(s, '--mzs-from', 0.84), v(s, '--mzs-img-from', 1)];
    }).filter(Boolean);
    for (const [s, p, f, i] of plan) { // потом все записи
      s.querySelector('.mzs__frame').style.transform = `scale(${(f + (1 - f) * p).toFixed(4)})`;
      s.querySelector('.mzs__img').style.transform = `scale(${(i + (1 - i) * p).toFixed(4)})`;
    }
  };
  const tick = () => { if (!raf) raf = requestAnimationFrame(frame); };
  addEventListener('scroll', tick, { passive: true, capture: true }); // capture — и прокрутка внутри контейнеров
  addEventListener('resize', tick);
  reduce.addEventListener('change', () => { if (!reduce.matches) { pick(); tick(); } }); // настройку меняют и на открытой странице
  pick(); tick();
})();

