// Только если GSAP уже есть в проекте: npm i gsap (Standard License, не MIT), без CDN. Разметка и CSS те же,
// но CSS-анимацию надо снять, иначе она спорит с GSAP: добавьте класс mzs-js на .mzs__stage (правило уже есть в CSS). JS рецепта не подключать.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', phone: '(max-width: 767px)' }, ({ conditions }) => {
  if (!conditions.motion) return; // reduce: кадр стоит в конечном виде
  gsap.utils.toArray('[data-mzs]').forEach((stage) => {
    stage.classList.add('mzs-js');
    const tl = gsap.timeline({
      defaults: { ease: 'none' }, // в scrub только без кривой: кривая спорит с прокруткой
      scrollTrigger: { trigger: stage, start: 'top bottom', end: () => '+=' + 0.4 * (innerHeight + stage.offsetHeight), scrub: true, invalidateOnRefresh: true },
    });
    tl.fromTo(stage.querySelector('.mzs__frame'), { scale: conditions.phone ? 0.94 : 0.84 }, { scale: 1 }, 0);
    if (!conditions.phone) tl.fromTo(stage.querySelector('.mzs__img'), { scale: 1.12 }, { scale: 1 }, 0);
  });
  return () => gsap.utils.toArray('[data-mzs]').forEach((s) => s.classList.remove('mzs-js'));
}); // оба условия в одном mm.add: при смене настройки matchMedia сам откатывает анимации
